#!/usr/bin/env python3
"""
Round 177b (culprits), 5 October 2026. Needs round 176b.

A note on the boxes; As drawn only once a colour is chosen.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 177b (5 October)\n\nNeeds round 176b (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Asked 5 October: a note under the drag note (#layer-drag-hint, second\n  span .lh-boxes) on what the boxes on each line do: a layer's tick box, a\n  heading's tick box, the colour square (one colour for a layer, or for\n  every ticked layer under a heading), and As drawn.\n- Asked whether As drawn is needed: it is the only way back to a layer's own\n  colours once a colour is chosen (a colour box cannot be emptied), so it\n  stays, but now appears only after a colour is chosen and goes away again\n  once used (.tint-off[hidden]); the square goes back to its starting colour.\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round177b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 176b" not in h.read_text(encoding="utf-8"):
        sys.exit("round177b: round 176b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round177b: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round177b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round177b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
